import re


def run(question, tools):
    # Portfolio requests: enforce entitlements before reading account data.
    m = re.search(r"\bA-\d+\b", question)
    if m:
        account = m.group(0)
        if not tools.is_authorized(account):
            return "UNAUTHORIZED"
        return str(tools.get_portfolio(account)["total_value"])

    # Identify the core question type to handle multi-hop and entity resolution better.
    # If the question asks about a parent company of another entity, we need two steps:
    # 1. Find the parent ticker of the mentioned company.
    # 2. Get the financials of that parent ticker.

    # Pattern to detect "parent company of X" or "owned by another listed company"
    parent_pattern = re.compile(r"(?:parent\s+company\s+of|owned by another listed company).*?(?i)(\w+)\s*(?:co\.?\s*)?", re.IGNORECASE)

    match_parent = parent_pattern.search(question)
    if match_parent:
        # Extract the child company name/ticker hint
        target_name_hint = match_parent.group(1).strip()

        # Step 1: Lookup the ticker of the child company mentioned
        try:
            child_ticker = tools.lookup_ticker(target_name_hint)
            if not child_ticker:
                # Fallback search if simple lookup fails, though direct lookup is preferred
                docs = tools.search(f"{target_name_hint} parent", k=4)
                for d in docs:
                    if "ticker" in str(d).lower() and "parent" in str(d).lower():
                        child_ticker = re.search(r"(?i)[a-z]{2}\d{3}", d.get("text", ""))
                        if child_ticker:
                            break
        except Exception:
            pass

        if not child_ticker:
            return "UNAUTHORIZED"  # Cannot proceed without knowing the parent

        try:
            parent_financials = tools.get_financials(child_ticker, "revenue", "FY2024")
            if parent_financials and parent_financials["value"] is not None:
                return str(parent_financials["value"])
        except Exception:
            pass

    # For other questions (growth, multihop without parent, restatement, etc.),
    # we search for relevant documents. The current harness searches once and asks the LLM.
    # However, to improve accuracy on multi-hop or growth questions where context might be scattered:

    docs = tools.search(question, k=4)
    context = "\n".join("- " + d["text"] for d in docs)

    # Refine prompt based on question type detected by simple keywords
    is_growth_question = "percent" in question.lower() or "percentage" in question.lower() or "change from" in question.lower()
    is_parent_question = bool(parent_pattern.search(question))

    if is_parent_question:
        # If we already found the parent, we might have answered. Otherwise, prompt LLM to find it.
        if child_ticker and (parent_financials and parent_financials["value"]):
            pass # Already handled above
        else:
            # Prompt LLM to resolve parent company first then get data
            prompt = (
                "First, identify the name of the parent company for the entity mentioned in the question. "
                "Then find its FY2024 revenue. Use the documents below.\n"
                f"Documents:\n{context}\n\n"
                f"Question: {question}\n"
                "Reply with only the final number (no units, no words)."
            )
    else:
        prompt = (
            "Use the documents to answer the question.\n"
            f"Documents:\n{context}\n\n"
            f"Question: {question}\n"
            "Reply with only the final number (no units, no words)."
        )

    try:
        return tools.llm(prompt, max_tokens=64).strip()
    except Exception:
        return "UNAUTHORIZED"
